</main><script>document.addEventListener('DOMContentLoaded',function(){var start=new Date('<?php echo esc_js(get_theme_mod('conf1405_event_start','2026-12-06T09:00:00'));?>'),end=new Date('<?php echo esc_js(get_theme_mod('conf1405_event_end','2026-12-08T18:00:00'));?>'),el=document.getElementById('home-countdown');function tick(){if(!el)return;var now=new Date();if(now<start){var d=start-now;el.textContent=Math.floor(d/86400000).toLocaleString('fa-IR')+' روز · '+Math.floor(d%86400000/3600000).toLocaleString('fa-IR')+' ساعت تا آغاز';}else if(now<=end){el.textContent='همایش در حال برگزاری است';}else{el.textContent='همایش به پایان رسیده است';}}tick();setInterval(tick,60000);});</script><?php get_footer(); ?>
